List<String> words = List.of("Go", "Java", "Python", "Rust");
String longest = words.stream().max(Comparator.comparingInt(String::length)).orElse("");
System.out.println(longest);

What is the output?

Map<String, Integer> scores = Map.of("Alice", 90, "Bob", 85, "Charlie", 95);
String top = scores.entrySet().stream()
    .max(Map.Entry.comparingByValue())
    .map(Map.Entry::getKey).orElse("");
System.out.println(top);

